// Device-bound offline vault cryptography. The encryption key is generated by WebCrypto,
// is non-extractable, and is persisted only in the browser's IndexedDB metadata.
const VERSION = 1;
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function assertUuid(value, label) {
  if (typeof value !== "string" || !UUID_RE.test(value)) throw new TypeError(label + " must be a UUID");
  return value.toLowerCase();
}
function toBase64Url(bytes) {
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}
function fromBase64Url(value) {
  if (typeof value !== "string" || !/^[A-Za-z0-9_-]+$/.test(value)) throw new TypeError("Invalid encoded vault data");
  const base64 = value.replace(/-/g, "+").replace(/_/g, "/") + "=".repeat((4 - value.length % 4) % 4);
  return Uint8Array.from(atob(base64), character => character.charCodeAt(0));
}
function aadFor(userId, deviceId) {
  return new TextEncoder().encode("tmh-offline-vault|" + VERSION + "|" + userId + "|" + deviceId);
}

export function createOfflineVaultCrypto({ cryptoImpl = globalThis.crypto } = {}) {
  if (!cryptoImpl?.subtle || typeof cryptoImpl.getRandomValues !== "function") {
    throw new TypeError("WebCrypto is required for offline vault encryption");
  }
  async function encryptBytes(key, bytes, aad) {
    const iv = cryptoImpl.getRandomValues(new Uint8Array(12));
    const ciphertext = await cryptoImpl.subtle.encrypt(
      { name: "AES-GCM", iv, additionalData: aad, tagLength: 128 }, key, bytes,
    );
    return { iv: toBase64Url(iv), ciphertext: toBase64Url(new Uint8Array(ciphertext)) };
  }
  async function decryptBytes(key, record, aad) {
    if (!record || typeof record !== "object") throw new TypeError("Invalid encrypted record");
    return new Uint8Array(await cryptoImpl.subtle.decrypt({
      name: "AES-GCM", iv: fromBase64Url(record.iv), additionalData: aad, tagLength: 128,
    }, key, fromBase64Url(record.ciphertext)));
  }
  async function encryptJson(key, value, userId, deviceId) {
    let json;
    try { json = JSON.stringify(value); }
    catch (error) { throw new TypeError("Value must be JSON serializable", { cause: error }); }
    if (json === undefined) throw new TypeError("Value must be JSON serializable");
    return Object.freeze({
      version: VERSION,
      ...(await encryptBytes(key, new TextEncoder().encode(json), aadFor(userId, deviceId))),
    });
  }
  async function decryptJson(key, record, userId, deviceId) {
    if (record?.version !== VERSION) throw new Error("Unsupported encrypted record version");
    const plaintext = await decryptBytes(key, record, aadFor(userId, deviceId));
    return JSON.parse(new TextDecoder().decode(plaintext));
  }
  function vaultFor(key, userId, deviceId) {
    return Object.freeze({
      encrypt: value => encryptJson(key, value, userId, deviceId),
      decrypt: record => decryptJson(key, record, userId, deviceId),
      encryptBytes: async bytes => {
        if (!(bytes instanceof ArrayBuffer) && !ArrayBuffer.isView(bytes)) {
          throw new TypeError("Binary data must be an ArrayBuffer or typed array");
        }
        const view = bytes instanceof ArrayBuffer ? new Uint8Array(bytes)
          : new Uint8Array(bytes.buffer, bytes.byteOffset, bytes.byteLength);
        return Object.freeze({ version: VERSION, ...(await encryptBytes(key, view, aadFor(userId, deviceId))) });
      },
      decryptBytes: async record => {
        if (record?.version !== VERSION) throw new Error("Unsupported encrypted record version");
        return decryptBytes(key, record, aadFor(userId, deviceId));
      },
    });
  }
  async function createDeviceKey() {
    return cryptoImpl.subtle.generateKey({ name: "AES-GCM", length: 256 }, false, ["encrypt", "decrypt"]);
  }
  function unlockWithDeviceKey({ key, userId, deviceId }) {
    const uid = assertUuid(userId, "userId");
    const did = assertUuid(deviceId, "deviceId");
    if (!key || key.type !== "secret" || key.algorithm?.name !== "AES-GCM" ||
        key.extractable !== false || !key.usages?.includes("encrypt") || !key.usages?.includes("decrypt")) {
      throw new TypeError("Invalid device encryption key");
    }
    return vaultFor(key, uid, did);
  }
  return Object.freeze({ createDeviceKey, unlockWithDeviceKey });
}
